const dayRows=d=>d.rows.map(a=>({p:a[0],n:a[1],c:a[2],i:'',s:a[3],r:a[4],t:a[5],pos:a[6],e:a[7],k:a[8]}));
const dayId=d=>new Date(d.t+'T12:00:00').getTime();
const LAST=DAYS[DAYS.length-1];
const SEED=dayRows(LAST);
const KEY='so_medali_v1';
let S;
try{S=JSON.parse(localStorage.getItem(KEY))}catch(e){}
if(!S||!S.rows){S={id:dayId(LAST),meta:{k:'MEDALI',c:'PURI',t:LAST.t,p:''},rows:SEED}}
if(!S.id)S.id=Date.now();
if(!Array.isArray(S.log))S.log=[];
const HK='so_medali_hist';
function getH(){try{return JSON.parse(localStorage.getItem(HK))||{}}catch(e){return{}}}
function putH(h){try{const s=JSON.stringify(h);localStorage.setItem(HK,s);return localStorage.getItem(HK)===s}catch(e){return false}}
(function(){try{if(localStorage.getItem('so_medali_seeded'))return;const h=getH();
DAYS.forEach(d=>{const id=dayId(d);if(!h[id])h[id]={meta:{k:'MEDALI',c:'PURI',t:d.t,p:''},rows:dayRows(d),log:[],last:null,upd:id}});
if(putH(h))localStorage.setItem('so_medali_seeded','1')}catch(e){}})();

function applyMeta(){$('mKdk').value=S.meta.k??'';$('mKec').value=S.meta.c??'';$('mTgl').value=S.meta.t??'';$('mPet').value=S.meta.p??''}
const $=id=>document.getElementById(id);
const num=v=>v===''||v==null?0:Number(v)||0;
const tot=r=>r.t!==''&&r.t!=null?num(r.t):num(r.c)*num(r.i)+num(r.s);
const filled=r=>r.c!==''||r.s!==''||r.r!==''||r.t!=='';
const sel=r=>filled(r)&&r.pos!==''?tot(r)-num(r.pos):null;

