function stats(){
  const f=S.rows.filter(filled);
  $('sDone').textContent=f.length+' / '+S.rows.length;
  $('sBar').style.width=(S.rows.length?f.length/S.rows.length*100:0)+'%';
  $('sTot').textContent=f.reduce((a,r)=>a+tot(r),0).toLocaleString('id-ID');
  const d=f.reduce((a,r)=>a+(sel(r)||0),0);$('sSel').textContent=(d>0?'+':'')+d.toLocaleString('id-ID');
  $('sRsk').textContent=S.rows.reduce((a,r)=>a+num(r.r),0).toLocaleString('id-ID');
}
